import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Month 2021: Optimizing Ceph on Arm64","description":"","frontmatter":{"title":"Ceph Month 2021: Optimizing Ceph on Arm64","date":"2021-06-23T00:00:00.000Z","updated":"2021-06-24T00:00:00.000Z","tags":["Ceph","Arm64","Optimization","Storage","Server"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Optimizing_Ceph_on_Arm64.md","filePath":"posts/2021/Ceph_Month_2021_-_Optimizing_Ceph_on_Arm64.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Month_2021_-_Optimizing_Ceph_on_Arm64.md"};function o(n,e,h,p,s,_){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-m64上的ceph优化实践" tabindex="-1">会议主题：M64上的Ceph优化实践 <a class="header-anchor" href="#会议主题-m64上的ceph优化实践" aria-label="Permalink to &quot;会议主题：M64上的Ceph优化实践&quot;">​</a></h4><h4 id="主讲人-rachel" tabindex="-1">主讲人：Rachel <a class="header-anchor" href="#主讲人-rachel" aria-label="Permalink to &quot;主讲人：Rachel&quot;">​</a></h4><h4 id="会议内容概述" tabindex="-1">会议内容概述： <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述：&quot;">​</a></h4><ol><li><p><strong>自我相关工作概述</strong>：</p><ul><li>Rachel介绍了在AMP服务器上进行安全存储生态系统实践的经验，包括使用UTF-8 DRC ISA等通用优化指令。</li><li>在M64平台上启用了多个服务器项目，如SPDK系统、Safe CSI等，并进行了优化。</li><li>支持使用Safe作为OpenStack和Kubernetes的存储后端。</li></ul></li><li><p><strong>优化工作</strong>：</p><ul><li>对UTF-8字符串处理和CRC-33实现进行了优化，分别提升了8倍和3倍的性能。</li><li>在ISA库中添加了对CRC IGB、AES GCM等算法的支持，并实现了多缓冲算法。</li><li>为M64添加了基于CPU特性集的实用函数，并提供了一个框架来生成基于特性集的最佳函数。</li></ul></li><li><p><strong>64KB内核页面的启用和基准测试</strong>：</p><ul><li>在M64平台上支持64KB内核页面，通过移除一级页表，提高了TLB查找速度和TLB命中率。</li><li>使用包含一个监控器、一个管理器和三个OSD的测试集群进行基准测试，结果显示使用64KB内核页面可以带来3%到11%的性能提升。</li></ul></li><li><p><strong>SPDK和DPDK的优化</strong>：</p><ul><li>SPDK通过将所有必要驱动程序移到用户空间并采用轮询模式，避免了内核上下文切换和中断处理开销。</li><li>DPDK采用了C11内存模型，优化了内存屏障的使用，并利用GCP的incoming CPU特性进行优化。</li></ul></li><li><p><strong>Ceph在ARM服务器上的性能状态</strong>：</p><ul><li>在ARM服务器上进行了Ceph的性能测试，结果显示在某些情况下SPDK并未带来明显的性能提升。</li></ul></li><li><p><strong>Ceph在C4上的工作</strong>：</p><ul><li>支持Ceph作为Kubernetes容器云存储后端，并添加了对关键容器镜像的支持。</li><li>正在进行的工作包括支持容器存储接口在线C4和Kubernetes存储e2e测试的改进。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续探索新的优化点，如利用可扩展向量扩展（SVE）和非临时性指令进行优化。</li><li>进一步研究和优化SPDK和DPDK在ARM架构上的性能。</li><li>继续支持Ceph在Kubernetes上的集成和优化。</li></ul><h4 id="会议讨论" tabindex="-1">会议讨论： <a class="header-anchor" href="#会议讨论" aria-label="Permalink to &quot;会议讨论：&quot;">​</a></h4><ul><li>讨论了ISA库在非Intel架构上的实现和使用，以及如何在混合CPU集群中安全使用ISA擦除编码。</li><li>探讨了在Raspberry Pi上使用ARM架构进行存储的可能性。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>Rachel感谢大家的参与和提问，并表示将继续进行相关研究和优化工作。</li></ul>',11)])])}const d=l(r,[["render",o]]);export{c as __pageData,d as default};
